styles.content:
.wf-rn {
  --rn-surface: var(--main-background1, var(--wf-color-surface, light-dark(#fff, #101a2b)));
  --rn-raised: var(--main-background2, var(--wf-color-background, light-dark(#f3f6fa, #162235)));
  --rn-text: var(--main-font-color, var(--wf-color-text, light-dark(#15253a, #e5edf8)));
  --rn-muted: var(--main-font-color-light, var(--wf-color-muted, light-dark(#4e6075, #b3c3d7)));
  --rn-line: var(--main-boder-color, var(--wf-color-border, light-dark(#d6dde6, #40516a)));
  --rn-accent: var(--main-button-background, var(--wf-color-primary, light-dark(#167261, #25d9c5)));
  box-sizing: border-box;
  width: min(100%, 1080px);
  margin-inline: auto;
  padding: 28px clamp(16px, 3vw, 32px) 48px;
  color: var(--rn-text);
  font-size: 14px;
}
.wf-rn *, .wf-rn *::before, .wf-rn *::after { box-sizing: border-box; }
.wf-rn [hidden] { display: none !important; }
.wf-rn-kicker { margin: 0 0 8px; font-size: 12px; }
.wf-rn-kicker a { color: var(--rn-accent); }
.wf-rn-title { margin: 0 0 6px; font-size: 28px; line-height: 1.2; }
.wf-rn-lead { margin: 0 0 20px; color: var(--rn-muted); }
.wf-rn-list-wrap { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 24px; align-items: start; }
.wf-rn-filters { padding: 14px; border: 1px solid var(--rn-line); border-radius: 8px; background: var(--rn-surface); }
.wf-rn-filters fieldset { margin: 0 0 14px; padding: 0; border: 0; }
.wf-rn-filters legend { color: var(--rn-muted); font-size: 12px; font-weight: 650; }
.wf-rn-option { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 8px; align-items: center; min-height: 32px; }
.wf-rn-search { display: grid; gap: 4px; margin-top: 8px; color: var(--rn-muted); font-size: 12px; }
.wf-rn-search input, .wf-rn button {
  min-height: 36px; padding: 6px 10px; border: 1px solid var(--rn-line); border-radius: 4px;
  color: var(--rn-text); background: var(--rn-surface); font: inherit;
}
.wf-rn-cards { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; }
.wf-rn-card {
  display: grid; gap: 6px; width: 100%; padding: 14px 16px; text-align: start;
  border: 1px solid var(--rn-line); border-radius: 8px; background: var(--rn-surface); color: var(--rn-text); font: inherit;
}
.wf-rn-card:hover { border-color: var(--rn-accent); background: var(--rn-raised); }
.wf-rn-meta, .wf-rn-feedback, .wf-rn-empty { color: var(--rn-muted); font-size: 12px; }
.wf-rn-article { overflow-wrap: anywhere; }
.wf-rn-article h2, .wf-rn-article h3 { margin: 1.2em 0 .4em; }
.wf-rn-pages { display: flex; justify-content: space-between; gap: 8px; margin-top: 12px; }
@media (max-width: 720px) {
  .wf-rn-list-wrap { grid-template-columns: 1fr; }
  .wf-rn-title { font-size: 22px; }
  .wf-rn button, .wf-rn-search input, .wf-rn-option { min-height: 44px; }
}

scripts.content:
(function () {
    'use strict';
    function decode(binding) {
        const bytes = Uint8Array.from(atob(binding.replace(/-/g, '+').replace(/_/g, '/')), value => value.charCodeAt(0));
        return JSON.parse(new TextDecoder().decode(bytes));
    }
    function encode(input) {
        const bytes = new TextEncoder().encode(JSON.stringify(input));
        return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }
    function text(tag, value, className) {
        const node = document.createElement(tag);
        node.textContent = value;
        if (className) node.className = className;
        return node;
    }
    function init(host) {
        const section = host.querySelector('.wf-rn');
        if (!section || section.dataset.rnReady) return;
        section.dataset.rnReady = 'true';
        const listWrap = section.querySelector('[data-rn-overview]');
        const detail = section.querySelector('[data-rn-detail]');
        const article = section.querySelector('[data-rn-article]');
        const cards = section.querySelector('ul[data-rn-list]');
        const feedback = section.querySelector('[data-rn-feedback]');
        const empty = section.querySelector('[data-rn-empty]');
        const pagination = section.querySelector('[data-rn-pagination]');
        const previous = section.querySelector('[data-rn-previous]');
        const next = section.querySelector('[data-rn-next]');
        const back = section.querySelector('[data-rn-back]');
        const clear = section.querySelector('[data-rn-clear]');
        const search = section.querySelector('[data-rn-query]');
        const groups = Object.fromEntries(Array.from(section.querySelectorAll('[data-rn-options]'), node => [node.dataset.rnOptions, node]));
        const selected = { tags: new Set(), types: new Set() };
        const previewBinding = host.dataset.wfProviderPreview;
        const preview = Boolean(previewBinding || host.hasAttribute('data-wf-provider-preview-error') || window.parent !== window);
        const sample = previewBinding ? decode(previewBinding) : null;
        let page = 1;
        let timer;
        let request;
        const english = document.documentElement.lang.toLowerCase().split('-')[0] === 'en';
        const t = (sr, en) => english ? en : sr;
        function load(input, signal) {
            const url = new URL(host.dataset.wfProviderUrl, window.location.href);
            url.searchParams.set('wf_input', encode(input));
            return fetch(url, { credentials: 'same-origin', cache: 'no-store', referrerPolicy: 'no-referrer', signal })
                .then(response => {
                    if (!response.ok) throw new Error(String(response.status));
                    return response.json();
                })
                .then(result => {
                    if (!result.ok) throw new Error('Provider response');
                    return result.data;
                });
        }
        function paintOptions(key, entries) {
            const group = groups[key];
            if (!group) return;
            const counts = new Map((entries || []).map(entry => [entry.label, entry.count]));
            for (const value of selected[key]) if (!counts.has(value)) counts.set(value, 0);
            const rows = Array.from(counts, ([label, count]) => {
                const option = text('label', '', 'wf-rn-option');
                const input = document.createElement('input');
                input.type = 'checkbox';
                input.value = label;
                input.checked = selected[key].has(label);
                option.append(input, text('span', label), text('span', String(count), 'wf-rn-meta'));
                return option;
            });
            group.replaceChildren(...rows);
        }
        function showList() {
            detail.hidden = true;
            listWrap.hidden = false;
        }
        function paint(data) {
            paintOptions('tags', data.tags);
            paintOptions('types', data.types);
            const active = selected.tags.size + selected.types.size;
            clear.hidden = active === 0 && search.value.trim() === '';
            empty.hidden = data.total !== 0;
            empty.textContent = search.value.trim()
                ? t('Nema beleški koje odgovaraju pretrazi.', 'No notes match your search.')
                : t('Nema objavljenih beleški za izabrane filtere.', 'No published notes match the selected filters.');
            page = data.page;
            pagination.hidden = page === 1 && !data['has-next'];
            previous.disabled = page === 1;
            next.disabled = !data['has-next'];
            feedback.textContent = data.total
                ? data.total + (data.total === 1 ? t(' beleška', ' note') : t(' beleški', ' notes'))
                : t('0 beleški', '0 notes');
            cards.replaceChildren(...(data.items || []).map(item => {
                const row = document.createElement('li');
                const card = text('button', '', 'wf-rn-card');
                card.type = 'button';
                card.dataset.rnSlug = item.slug;
                const meta = text('p', '', 'wf-rn-meta');
                meta.textContent = [item.date, item.type, (item.tags || []).join(', ')].filter(Boolean).join(' · ');
                card.append(meta, text('strong', item.title));
                if (item.summary) card.append(text('span', item.summary, 'wf-rn-meta'));
                card.addEventListener('click', () => openNote(item.slug, true));
                row.append(card);
                return row;
            }));
            listWrap.dataset.rnState = 'ready';
        }
        async function updateList() {
            request?.abort();
            request = new AbortController();
            const { signal } = request;
            cards.setAttribute('aria-busy', 'true');
            try {
                const input = { page };
                const query = search.value.trim();
                if (query) input.q = query;
                if (selected.tags.size) input.tags = [...selected.tags];
                if (selected.types.size) input.types = [...selected.types];
                const data = preview ? (sample || { items: [], total: 0, page: 1, 'has-next': false, tags: [], types: [] }) : await load(input, signal);
                if (!signal.aborted) paint(data);
            } catch (error) {
                if (signal.aborted) return;
                listWrap.dataset.rnState = 'error';
                feedback.textContent = t('Beleške trenutno nisu dostupne.', 'Notes are currently unavailable.');
                cards.replaceChildren();
            } finally {
                cards.removeAttribute('aria-busy');
            }
        }
        async function openNote(slug, push) {
            request?.abort();
            request = new AbortController();
            const { signal } = request;
            listWrap.hidden = true;
            detail.hidden = false;
            article.replaceChildren(text('p', t('Učitavanje…', 'Loading…'), 'wf-rn-feedback'));
            if (push && window.parent === window) {
                const url = new URL(window.location.href);
                url.searchParams.set('slug', slug);
                history.pushState({ ...history.state, wfReleaseNotes: slug }, '', url);
            }
            try {
                const data = preview
                    ? { item: (sample?.items || []).concat(sample?.item ? [sample.item] : []).find(row => row.slug === slug) }
                    : await load({ slug }, signal);
                const item = data.item;
                if (!item?.slug) throw new Error('404');
                const heading = text('h1', item.title, 'wf-rn-title');
                const meta = text('p', [item.date, item.type, (item.tags || []).join(', ')].filter(Boolean).join(' · '), 'wf-rn-meta');
                const body = document.createElement('div');
                body.className = 'wf-rn-article';
                body.innerHTML = item.html || '';
                article.replaceChildren(heading, meta, body);
                back.focus({ preventScroll: true });
            } catch (error) {
                article.replaceChildren(text('p', t('Beleška više nije dostupna.', 'This note is no longer available.')));
            }
        }
        for (const [key, group] of Object.entries(groups)) {
            group.addEventListener('change', event => {
                const input = event.target;
                if (input.type !== 'checkbox') return;
                if (input.checked) selected[key].add(input.value);
                else selected[key].delete(input.value);
                page = 1;
                updateList();
            });
        }
        clear.addEventListener('click', () => {
            selected.tags.clear();
            selected.types.clear();
            search.value = '';
            page = 1;
            updateList();
        });
        search.addEventListener('input', () => {
            window.clearTimeout(timer);
            page = 1;
            timer = window.setTimeout(updateList, 220);
        });
        previous.addEventListener('click', () => { page--; updateList(); });
        next.addEventListener('click', () => { page++; updateList(); });
        back.addEventListener('click', () => {
            if (window.parent === window && history.state?.wfReleaseNotes) history.back();
            else {
                const url = new URL(window.location.href);
                url.searchParams.delete('slug');
                history.replaceState(history.state, '', url);
                showList();
            }
        });
        if (window.parent === window) {
            window.addEventListener('popstate', () => {
                const slug = new URL(window.location.href).searchParams.get('slug');
                if (slug) openNote(slug, false);
                else showList();
            });
        }
        const startSlug = new URL(window.location.href).searchParams.get('slug');
        updateList();
        if (startSlug) openNote(startSlug, false);
    }
    document.querySelectorAll('[data-wf-component="release-notes"]').forEach(init);
}());
